import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata, TurnUsage} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage facet test.'});
const session = (): ChatSession => ({
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

describe('afterModelResponse TurnUsage aggregation', () => {
  it('receives TurnUsage with total and rounds', async () => {
    let receivedUsage: TurnUsage | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 2, totalTokens: 12})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 3, totalTokens: 23})],
      ]),
      promptBuilder,
      new ToolRegistry(), // Registry with no tools will still allow the loop to continue once if scripted
      {hooks}
    );

    // I need a registry that actually has the tool to continue the loop
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'desc', inputSchema: {}}, async () => 'result');

    const orchestrator2 = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 2, totalTokens: 12})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 3, totalTokens: 23})],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator2.processMessage(session());

    expect(receivedUsage).toBeDefined();
    expect(receivedUsage?.total).toEqual({inputTokens: 30, outputTokens: 5, totalTokens: 35});
    expect(receivedUsage?.rounds).toHaveLength(2);
    expect(receivedUsage?.rounds[0]).toEqual({inputTokens: 10, outputTokens: 2, totalTokens: 12});
    expect(receivedUsage?.rounds[1]).toEqual({inputTokens: 20, outputTokens: 3, totalTokens: 23});
  });
});

