}

import type {TurnUsage} from '../types/ai.js';

export function summarizeUsage(rounds: UsageMetadata[]): TurnUsage | undefined {
  if (rounds.length === 0) return undefined;

  const total = rounds.reduce(
    (acc, round) => ({
      inputTokens: acc.inputTokens + round.inputTokens,
      outputTokens: acc.outputTokens + round.outputTokens,
      totalTokens: acc.totalTokens + round.totalTokens,
    }),
    {inputTokens: 0, outputTokens: 0, totalTokens: 0}
  );

  return {total, rounds};
}

